// Filter buttons shown above the list, in display order.
// `all` is special and matches everything; any other `key` matches papers
// whose `categories` array includes that key. To add a category later,
// add an entry here and tag the relevant papers above with the same key.
// Available category keys: selected, conference, workshop, preprint, project, poster.
export const publicationFilters = [
  { key: 'all', label: 'All' },
  { key: 'selected', label: 'Selected' }
  // e.g. { key: 'conference', label: 'Conference' },
  //      { key: 'workshop', label: 'Workshop' },
  //      { key: 'preprint', label: 'Preprints' }
];

// `all` matches everything; any other key matches a publication's `categories`.
export const matchesFilter = (publication, key) =>
  key === 'all' || (publication.categories || []).includes(key);

export default publicationsData;
